src = r'''
import hou, math
FPS = 24.0
FLAP_MIN = -15.0   # lower bound: below this the wing root would cut into thorax/legs
FLAP_MAX = 85.0
EYE = hou.Vector3(0.0, 1.0, 0.04)   # girl eye point (rest), used as look-at pivot

def _bf():
    return hou.node('/obj/butterfly/CTRL_body')

def _hc():
    return hou.node('/obj/hand_contact')

def _v3(n, name, f):
    return hou.Vector3([n.parm(name + c).evalAtFrame(f) for c in 'xyz'])

def bf_base(f):
    """Authored spline path blended (att) with hand_contact-relative hover/landing offset."""
    n = _bf()
    P = _v3(n, 'path_t', f)
    a = n.parm('att').evalAtFrame(f)
    if a <= 0.0:
        return P
    O = _v3(n, 'hov_t', f)
    H = _hc().worldTransformAtTime(hou.frameToTime(f))
    Hp = O * H
    if a >= 1.0:
        return Hp
    return P * (1.0 - a) + Hp * a

def bob(f):
    """Low amplitude vertical bobbing layer (sine + sine-sum pseudo noise), weighted by bob_w."""
    n = _bf()
    w = n.parm('bob_w').evalAtFrame(f)
    if w <= 0.0:
        return hou.Vector3(0, 0, 0)
    t = f / FPS
    amp = n.parm('bob_amp').evalAtFrame(f)
    y = amp * (0.7 * math.sin(2 * math.pi * 1.15 * t + 0.4)
               + 0.2 * math.sin(2 * math.pi * 2.73 * t + 1.3)
               + 0.1 * math.sin(2 * math.pi * 4.31 * t + 2.1))
    x = amp * 0.3 * math.sin(2 * math.pi * 0.83 * t + 0.9)
    return hou.Vector3(x * w, y * w, 0.0)

def bf_world(f):
    return bf_base(f) + bob(f)

def bf_pos(i):
    return bf_world(hou.frame())[i]

def _flight_rot(f):
    v = bf_base(f + 1) - bf_base(f - 1)
    if v.length() < 1e-5:
        fwd = hou.Vector3(0, 0, 1)
    else:
        fwd = v.normalized()
    # limit pitch
    h = math.hypot(fwd[0], fwd[2])
    if h < 1e-4:
        fwd = hou.Vector3(0, 0, 1); h = 1.0
    pitch = max(-0.45, min(0.45, math.atan2(fwd[1], h)))
    yaw = math.atan2(fwd[0], fwd[2])
    fwd = hou.Vector3(math.sin(yaw) * math.cos(pitch), math.sin(pitch), math.cos(yaw) * math.cos(pitch))
    up = hou.Vector3(0, 1, 0)
    X = up.cross(fwd).normalized()
    Y = fwd.cross(X).normalized()
    # bank from lateral acceleration
    acc = bf_base(f + 2) - bf_base(f) * 2.0 + bf_base(f - 2)
    bank = max(-0.35, min(0.35, -acc.dot(X) * 40.0))
    cb, sb = math.cos(bank), math.sin(bank)
    X2 = X * cb + Y * sb
    Y2 = Y * cb - X * sb
    return hou.Matrix3(((X2[0], X2[1], X2[2]), (Y2[0], Y2[1], Y2[2]), (fwd[0], fwd[1], fwd[2])))

def bf_rot(i):
    f = hou.frame()
    n = _bf()
    r = max(0.0, min(1.0, n.parm('rot_att').evalAtFrame(f)))
    qF = hou.Quaternion(_flight_rot(f))
    if r > 0.0:
        qH = hou.Quaternion(_hc().worldTransformAtTime(hou.frameToTime(f)).extractRotationMatrix3())
        q = qF.slerp(qH, r)
    else:
        q = qF
    m = hou.Matrix4(q.extractRotationMatrix3())
    return m.extractRotates('srt', 'xyz')[i]

def _phase(f):
    p = _bf().parm('flap_freq')
    ph = 0.0
    k = 1
    while k + 1 <= f:
        ph += 0.5 * (p.evalAtFrame(k) + p.evalAtFrame(k + 1)) / FPS
        k += 1
    if f > k:
        ph += p.evalAtFrame(f) * (f - k) / FPS
    return ph

def bf_flap(side=0):
    """Wing flap: integrated-frequency sine cycle blended with keyed slow open/close, clamped."""
    n = _bf(); f = hou.frame()
    w = max(0.0, min(1.0, n.parm('flap_cyc_w').evalAtFrame(f)))
    v = 0.0
    if w > 0.0:
        cyc = n.parm('flap_mid').evalAtFrame(f) + n.parm('flap_amp').evalAtFrame(f) * math.sin(2 * math.pi * _phase(f))
        v += w * cyc
    if w < 1.0:
        v += (1.0 - w) * n.parm('flap_key').evalAtFrame(f)
    return max(FLAP_MIN, min(FLAP_MAX, v))

def _look(f):
    d = bf_world(max(1.0, f)) - EYE
    yaw = math.degrees(math.atan2(d[0], d[2]))
    pitch = math.degrees(math.atan2(-d[1], math.hypot(d[0], d[2])))
    return max(-35.0, min(40.0, pitch)), max(-75.0, min(75.0, yaw))

def head_rot(i):
    """Head look-at toward butterfly with time lag (look_lag frames) + 5-tap smoothing, blended with keyed base pose."""
    c = hou.node('/obj/anim_ctrl'); f = hou.frame()
    w = max(0.0, min(1.0, c.parm('look_w').evalAtFrame(f)))
    base = c.parm('head_base_x' if i == 0 else 'head_base_y').evalAtFrame(f)
    if w <= 0.0:
        return base
    lag = c.parm('look_lag').evalAtFrame(f)
    acc = 0.0; ws = 0.0
    for o, k in ((-2, 1.0), (-1, 2.0), (0, 3.0), (1, 2.0), (2, 1.0)):
        acc += k * _look(f - lag + o)[i]; ws += k
    look = acc / ws + (c.parm('head_off_x' if i == 0 else 'head_off_y').evalAtFrame(f))
    return (1.0 - w) * base + w * look
